class Shape {
    protected String name;
    public Shape(String name) { this.name = name; }
    public double area() { return 0; }
    @Override public String toString() { return name + " area=" + area(); }
}
class Circle extends Shape {
    private double r;
    public Circle(double r) { super("Circle"); this.r = r; }
    @Override public double area() { return Math.PI * r * r; }
    public void roll() { System.out.println("rolling"); }
}
class Rectangle extends Shape {
    private double w, h;
    public Rectangle(double w, double h) { super("Rectangle"); this.w = w; this.h = h; }
    @Override public double area() { return w * h; }
}
public class Main {
    public static void main(String[] args) {
        Shape[] shapes = { new Circle(5), new Rectangle(4, 6) };
        for (Shape s : shapes) {
            System.out.println(s);             // runtime polymorphism
            if (s instanceof Circle) ((Circle) s).roll();
        }
    }
}

