class Employee {
  protected String name; protected double base;
  Employee(String n, double b) { name = n; base = b; }
  double pay() { return base; }
}
class Manager extends Employee {
  private double bonus;
  Manager(String n, double b, double bonus) { super(n, b); this.bonus = bonus; }
  @Override double pay() { return super.pay() + bonus; }
}
Employee[] e = { new Employee("Kabo", 5000), new Manager("Neo", 8000, 2000) };
for (Employee x : e) System.out.println(x.name + " " + x.pay());
